import { Module } from '@nestjs/common';
import { ToolsService } from './tools.service.js';
import { RepositoryTool } from './model/repository.tool.js';
import { CategoriesModule } from '../categories/categories.module.js';
import { UsageLogsModule } from '../usage-logs/usage-logs.module.js';
import { ToolsController } from './tools.controller.js';

@Module({
  imports: [CategoriesModule, UsageLogsModule],
  providers: [ToolsService, RepositoryTool],
  controllers: [ToolsController],
})
export class ToolsModule {}

@Controller('api/tools')
export class ToolsController {
  private readonly logger = new Logger(ToolsController.name);
  constructor(private readonly toolService: ToolsService) {}

  @Post()
  async create(@Body() data: CreateToolDto) {
    return this.toolService.createTool(data);
  }

const pagination: PaginationFilters = {};
const filters: FiltersDto = {};
const sortField: Record<string, string> = {};
if (queries.page !== undefined) pagination.page = queries.page;
if (queries.limit !== undefined) pagination.limit = queries.limit;
if (queries.category) filters.category = queries.category;
if (queries.department) 
  filters.department =
    tools_owner_department[
      queries.department as keyof typeof tools_owner_department
    ];

async createTool(data: CreateToolDto) {
  const categorie = await this.categoriesService.getById(data.category_id);
  if (!categorie)
    throw new NotFoundException({
      error: 'Categorie not found',
      message: `Categorie with ID ${data.category_id} does not exist`,
    });
    this.logger.error("Categorie not found")
  const result = await this.repository.create(data);
  return {...result, monthly_cost: Number(result.monthly_cost.toFixed(2))}
}

getFiltersWhere(filters: FiltersDto) {
  const whereFilters: Record<string, unknown> = {};
  if (filters.category)
    whereFilters['categories'] = { name: { equals: filters.category } };
  if (filters.department)
    whereFilters['owner_department'] = filters.department;
  if (filters.min_cost !== undefined && filters.max_cost !== undefined) {
    whereFilters['AND'] = [
      { monthly_cost: { lte: filters.max_cost } },
      { monthly_cost: { gte: filters.min_cost } }
    ]
  }

export class CreateToolDto {
  @IsString()
  @Length(2, 100)
  @IsNotEmpty()
  name: string;

  @IsOptional()
  @IsString()
  description?: string;

  @IsString()
  @Length(1, 100)
  @IsNotEmpty()
  vendor: string;

  @IsUrl()
  @IsOptional()
  website_url?: string;

  @IsEnum(tools_owner_department)
  @IsNotEmpty()
  owner_department: tools_owner_department;

  @IsNumber({ maxDecimalPlaces: 2 })
  @IsNotEmpty()
  @Min(0)
  monthly_cost: number;

  @IsNumber()
  @IsNotEmpty()
  @Min(1)
  category_id: number;
}

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.useGlobalPipes(new ValidationPipe({transform: true}));
  const config = new DocumentBuilder()
    .setTitle('Internal tools management')
    .setDescription('The internal tools management API description')
    .setVersion('1.0')
    .addTag('internal_tools_management')
    .build();
  const documentFactory = () => SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api/docs', app, documentFactory);
  await app.listen(process.env.PORT ?? 3000);
}

@Injectable()
export class ToolsService {
  private readonly logger = new Logger(ToolsService.name);
  constructor(
    private readonly repository: RepositoryTool,
    private readonly categoriesService: CategoriesService,
    private readonly usageLogs: UsageLogsService,
  ) {}

@Module({
  providers: [CategoriesService, CategoriesRepository],
  exports: [CategoriesService],
})
export class CategoriesModule {}
